use std::cell::RefCell;
use std::cmp::Ordering;
use std::collections::BTreeMap;
use std::rc::Rc;
use crate::lexer::Position;
use crate::parser::{Expression, ExprKind, Parameter, Pattern, PatternKind, Group};
#[derive(Clone)]
pub enum Value { Integer(i64), Boolean(bool), String(String), Pair(Box<Value>, Box<Value>), List(Vec<Value>), Closure(Rc<Closure>), Builtin(String) }
pub type Environment = BTreeMap<String, Value>;
pub struct Closure { parameter: Parameter, body: Expression, environment: Rc<RefCell<Environment>> }
pub struct Error { pub position: Position, pub message: String }
pub struct Evaluator { pub calls: usize }
fn error(position: Position, message: &str) -> Error { Error { position, message: message.into() } }
fn integer(value: i64, position: Position) -> Result<Value, Error> {
    if (-2147483648..=2147483647).contains(&value) { Ok(Value::Integer(value)) } else { Err(error(position, "integer overflow")) }
}
fn compare(a: &Value, b: &Value, position: Position) -> Result<Ordering, Error> {
    match (a, b) {
        (Value::Integer(a), Value::Integer(b)) => Ok(a.cmp(b)), (Value::Boolean(a), Value::Boolean(b)) => Ok(a.cmp(b)),
        (Value::String(a), Value::String(b)) => Ok(a.cmp(b)),
        (Value::Pair(a, b), Value::Pair(c, d)) => { let first = compare(a, c, position)?; if first.is_eq() { compare(b, d, position) } else { Ok(first) } },
        (Value::List(a), Value::List(b)) => {
            for (a, b) in a.iter().zip(b) { let order = compare(a, b, position)?; if !order.is_eq() { return Ok(order); } }
            Ok(a.len().cmp(&b.len()))
        },
        _ => Err(error(position, "functional value compared"))
    }
}
fn matches(pattern: &Pattern, value: &Value, bindings: &mut Environment) -> bool {
    match (&pattern.kind, value) {
        (PatternKind::Wildcard, _) => true,
        (PatternKind::Name(name), _) => { bindings.insert(name.clone(), value.clone()); true },
        (PatternKind::Integer(a), Value::Integer(b)) => a == b,
        (PatternKind::Boolean(a), Value::Boolean(b)) => a == b,
        (PatternKind::String(a), Value::String(b)) => a == b,
        (PatternKind::Nil, Value::List(values)) => values.is_empty(),
        (PatternKind::Cons(a, b), Value::List(values)) => !values.is_empty() && matches(a, &values[0], bindings) && matches(b, &Value::List(values[1..].to_vec()), bindings),
        (PatternKind::List(patterns), Value::List(values)) => patterns.len() == values.len() && patterns.iter().zip(values).all(|(p, v)| matches(p, v, bindings)),
        (PatternKind::Pair(a, b), Value::Pair(c, d)) => matches(a, c, bindings) && matches(b, d, bindings),
        _ => false
    }
}
impl Evaluator {
    pub fn group(&mut self, group: &Group, environment: &Environment) -> Result<(Environment, Vec<Value>), Error> {
        let mut values = Vec::new();
        if group.recursive.is_some() {
            let shared = Rc::new(RefCell::new(environment.clone()));
            for binding in &group.bindings {
                if let ExprKind::Fun(parameter, body) = &binding.expression.kind {
                    values.push(Value::Closure(Rc::new(Closure { parameter: parameter.clone(), body: body.clone(), environment: shared.clone() })));
                }
            }
            for (binding, value) in group.bindings.iter().zip(&values) { shared.borrow_mut().insert(binding.name.clone(), value.clone()); }
            let result = shared.borrow().clone();
            Ok((result, values))
        } else {
            for binding in &group.bindings { values.push(self.expression(&binding.expression, environment)?); }
            let mut result = environment.clone();
            for (binding, value) in group.bindings.iter().zip(&values) { result.insert(binding.name.clone(), value.clone()); }
            Ok((result, values))
        }
    }
    fn apply(&mut self, function: Value, argument: Value, position: Position) -> Result<Value, Error> {
        self.calls += 1;
        match function {
            Value::Closure(closure) => {
                let mut environment = closure.environment.borrow().clone();
                if let Some(name) = &closure.parameter.name { environment.insert(name.clone(), argument); }
                self.expression(&closure.body, &environment)
            },
            Value::Builtin(name) => match (name.as_str(), argument) {
                ("fst", Value::Pair(a, _)) => Ok(*a), ("snd", Value::Pair(_, b)) => Ok(*b),
                ("not", Value::Boolean(value)) => Ok(Value::Boolean(!value)),
                ("string_of_int", Value::Integer(value)) => Ok(Value::String(value.to_string())),
                ("failwith", Value::String(value)) => Err(Error { position, message: format!("failure {}", crate::quote(&value)) }),
                _ => unreachable!()
            },
            _ => unreachable!()
        }
    }
    pub fn expression(&mut self, expression: &Expression, environment: &Environment) -> Result<Value, Error> {
        match &expression.kind {
            ExprKind::Integer(value) => Ok(Value::Integer(*value)), ExprKind::Boolean(value) => Ok(Value::Boolean(*value)),
            ExprKind::String(value) => Ok(Value::String(value.clone())), ExprKind::Name(name) => Ok(environment[name].clone()),
            ExprKind::Fun(parameter, body) => Ok(Value::Closure(Rc::new(Closure { parameter: parameter.clone(), body: body.clone(), environment: Rc::new(RefCell::new(environment.clone())) }))),
            ExprKind::Apply(function, argument) => { let function = self.expression(function, environment)?; let argument = self.expression(argument, environment)?; self.apply(function, argument, expression.position) },
            ExprKind::Negate(position, value) => { if let Value::Integer(value) = self.expression(value, environment)? { integer(-value, *position) } else { unreachable!() } },
            ExprKind::Binary(operator, position, a, b) => {
                let left = self.expression(a, environment)?;
                if operator == "&&" { if let Value::Boolean(value) = left { return if value { self.expression(b, environment) } else { Ok(Value::Boolean(false)) }; } }
                if operator == "||" { if let Value::Boolean(value) = left { return if value { Ok(Value::Boolean(true)) } else { self.expression(b, environment) }; } }
                let right = self.expression(b, environment)?;
                match operator.as_str() {
                    "+" | "-" | "*" | "/" | "mod" => if let (Value::Integer(a), Value::Integer(b)) = (left, right) {
                        if (operator == "/" || operator == "mod") && b == 0 { return Err(error(*position, "division by zero")); }
                        let value = match operator.as_str() { "+" => a + b, "-" => a - b, "*" => a * b, "/" => a / b, _ => a - b * (a / b) };
                        integer(value, *position)
                    } else { unreachable!() },
                    "^" => if let (Value::String(a), Value::String(b)) = (left, right) { Ok(Value::String(a + &b)) } else { unreachable!() },
                    "::" => if let Value::List(mut values) = right { values.insert(0, left); Ok(Value::List(values)) } else { unreachable!() },
                    _ => { let order = compare(&left, &right, *position)?; let value = match operator.as_str() { "=" => order.is_eq(), "<>" => !order.is_eq(), "<" => order.is_lt(), ">" => order.is_gt(), "<=" => order.is_le(), _ => order.is_ge() }; Ok(Value::Boolean(value)) }
                }
            },
            ExprKind::If(condition, yes, no) => if let Value::Boolean(value) = self.expression(condition, environment)? { self.expression(if value { yes } else { no }, environment) } else { unreachable!() },
            ExprKind::Pair(a, b) => { let a = self.expression(a, environment)?; let b = self.expression(b, environment)?; Ok(Value::Pair(Box::new(a), Box::new(b))) },
            ExprKind::List(elements) => { let mut values = Vec::new(); for element in elements { values.push(self.expression(element, environment)?); } Ok(Value::List(values)) },
            ExprKind::Match(value, arms) => {
                let value = self.expression(value, environment)?;
                for (pattern, body) in arms { let mut bindings = BTreeMap::new(); if matches(pattern, &value, &mut bindings) { let mut inner = environment.clone(); inner.extend(bindings); return self.expression(body, &inner); } }
                Err(error(expression.position, "match failure"))
            },
            ExprKind::Let(group, body) => { let (inner, _) = self.group(group, environment)?; self.expression(body, &inner) }
        }
    }
}

use std::collections::{BTreeMap, BTreeSet};
use crate::lexer::Position;
use crate::parser::{Expression, ExprKind, Group, Pattern, PatternKind};
use crate::unifier::{Type, Scheme, Environment, Unifier, Failure};
pub enum ErrorKind { Message(String), Function(Type), Check(Type, Type, Failure) }
pub struct Error { pub position: Position, pub kind: ErrorKind }
pub struct Local { pub name: String, pub position: Position, pub scheme: Scheme }
pub struct Context { pub unifier: Unifier, pub locals: Vec<Local>, pub matches: BTreeMap<Position, (Type, Vec<Pattern>)> }
impl Context {
    pub fn new() -> Self { Self { unifier: Unifier::new(), locals: Vec::new(), matches: BTreeMap::new() } }
    pub fn clear(&mut self) { self.locals.clear(); self.matches.clear(); }
    fn message(&self, position: Position, message: String) -> Error { Error { position, kind: ErrorKind::Message(message) } }
    fn check(&mut self, expected: &Type, found: &Type, position: Position) -> Result<(), Error> {
        self.unifier.unify(expected, found).map_err(|failure| Error { position, kind: ErrorKind::Check(expected.clone(), found.clone(), failure) })
    }
    pub fn group(&mut self, group: &Group, environment: &Environment, local: bool) -> Result<(Environment, Vec<Scheme>), Error> {
        let mut names = BTreeSet::new();
        for binding in &group.bindings {
            if !names.insert(binding.name.clone()) { return Err(self.message(binding.position, format!("variable '{}' is bound twice in this let", binding.name))); }
            if group.recursive.is_some() && !matches!(&binding.expression.kind, ExprKind::Fun(..)) { return Err(self.message(binding.position, format!("'{}' in let rec must be a function", binding.name))); }
        }
        let mut recursive = environment.clone();
        let mut types = Vec::new();
        if group.recursive.is_some() {
            for binding in &group.bindings { let ty = self.unifier.fresh(); recursive.insert(binding.name.clone(), Scheme::mono(ty.clone())); types.push(ty); }
            for (i, binding) in group.bindings.iter().enumerate() {
                let found = self.expression(&binding.expression, &recursive)?;
                self.check(&types[i], &found, binding.position)?;
            }
        } else { for binding in &group.bindings { types.push(self.expression(&binding.expression, environment)?); } }
        let schemes: Vec<_> = types.into_iter().map(|ty| self.unifier.generalize(ty, environment)).collect();
        let mut result = environment.clone();
        for (binding, scheme) in group.bindings.iter().zip(&schemes) {
            result.insert(binding.name.clone(), scheme.clone());
            if local { self.locals.push(Local { name: binding.name.clone(), position: binding.position, scheme: scheme.clone() }); }
        }
        Ok((result, schemes))
    }
    pub fn expression(&mut self, expression: &Expression, environment: &Environment) -> Result<Type, Error> {
        match &expression.kind {
            ExprKind::Integer(_) => Ok(Type::Integer), ExprKind::Boolean(_) => Ok(Type::Boolean), ExprKind::String(_) => Ok(Type::String),
            ExprKind::Name(name) => if let Some(scheme) = environment.get(name) { Ok(self.unifier.instantiate(scheme)) } else {
                let candidate = environment.keys().map(|candidate| (crate::edit_distance(name, candidate), candidate)).filter(|(distance, _)| *distance <= 2 && *distance < name.len()).min();
                let suffix = candidate.map_or_else(String::new, |(_, candidate)| format!(" (did you mean '{}'?)", candidate));
                Err(self.message(expression.position, format!("unbound variable '{}'{}", name, suffix)))
            },
            ExprKind::Fun(parameter, body) => {
                let argument = self.unifier.fresh(); let mut inner = environment.clone();
                if let Some(name) = &parameter.name { inner.insert(name.clone(), Scheme::mono(argument.clone())); }
                let result = self.expression(body, &inner)?; Ok(Type::function(argument, result))
            },
            ExprKind::Apply(function, argument) => {
                let function_type = self.expression(function, environment)?;
                let (expected, result) = match self.unifier.resolve(&function_type) {
                    Type::Variable(index) => { let a = self.unifier.fresh(); let b = self.unifier.fresh(); self.unifier.bind(index, Type::function(a.clone(), b.clone())); (a, b) },
                    Type::Function(a, b) => (*a, *b),
                    ty => return Err(Error { position: function.position, kind: ErrorKind::Function(ty) })
                };
                let found = self.expression(argument, environment)?; self.check(&expected, &found, argument.position)?; Ok(result)
            },
            ExprKind::Binary(operator, _, left, right) => {
                let (a, b, result) = match operator.as_str() {
                    "+" | "-" | "*" | "/" | "mod" => (Type::Integer, Type::Integer, Type::Integer),
                    "^" => (Type::String, Type::String, Type::String), "&&" | "||" => (Type::Boolean, Type::Boolean, Type::Boolean),
                    "::" => { let a = self.unifier.fresh(); (a.clone(), Type::list(a.clone()), Type::list(a)) },
                    _ => { let a = self.unifier.fresh(); (a.clone(), a, Type::Boolean) }
                };
                let found = self.expression(left, environment)?; self.check(&a, &found, left.position)?;
                let found = self.expression(right, environment)?; self.check(&b, &found, right.position)?; Ok(result)
            },
            ExprKind::Negate(_, value) => { let found = self.expression(value, environment)?; self.check(&Type::Integer, &found, value.position)?; Ok(Type::Integer) },
            ExprKind::If(condition, yes, no) => {
                let found = self.expression(condition, environment)?; self.check(&Type::Boolean, &found, condition.position)?;
                let yes_type = self.expression(yes, environment)?; let no_type = self.expression(no, environment)?;
                self.check(&yes_type, &no_type, no.position)?; Ok(yes_type)
            },
            ExprKind::Pair(a, b) => { let a = self.expression(a, environment)?; let b = self.expression(b, environment)?; Ok(Type::pair(a, b)) },
            ExprKind::List(elements) => {
                let ty = self.unifier.fresh();
                for value in elements { let found = self.expression(value, environment)?; self.check(&ty, &found, value.position)?; }
                Ok(Type::list(ty))
            },
            ExprKind::Match(value, arms) => {
                let ty = self.expression(value, environment)?; let result = self.unifier.fresh();
                for (pattern, body) in arms {
                    let mut bindings = BTreeMap::new(); let found = self.pattern(pattern, &mut bindings)?;
                    self.check(&ty, &found, pattern.position)?;
                    let mut inner = environment.clone();
                    for (name, ty) in bindings { inner.insert(name, Scheme::mono(ty)); }
                    let found = self.expression(body, &inner)?; self.check(&result, &found, body.position)?;
                }
                self.matches.insert(expression.position, (ty, arms.iter().map(|(pattern, _)| pattern.clone()).collect()));
                Ok(result)
            },
            ExprKind::Let(group, body) => { let (inner, _) = self.group(group, environment, true)?; self.expression(body, &inner) }
        }
    }
    fn pattern(&mut self, pattern: &Pattern, bindings: &mut BTreeMap<String, Type>) -> Result<Type, Error> {
        match &pattern.kind {
            PatternKind::Wildcard => Ok(self.unifier.fresh()),
            PatternKind::Name(name) => {
                if bindings.contains_key(name) { return Err(self.message(pattern.position, format!("variable '{}' is bound twice in this pattern", name))); }
                let ty = self.unifier.fresh(); bindings.insert(name.clone(), ty.clone()); Ok(ty)
            },
            PatternKind::Integer(_) => Ok(Type::Integer), PatternKind::Boolean(_) => Ok(Type::Boolean), PatternKind::String(_) => Ok(Type::String),
            PatternKind::Nil => Ok(Type::list(self.unifier.fresh())),
            PatternKind::Cons(a, b) => {
                let ty = self.unifier.fresh(); let head = self.pattern(a, bindings)?; self.check(&ty, &head, a.position)?;
                let tail = self.pattern(b, bindings)?; let list = Type::list(ty); self.check(&list, &tail, b.position)?; Ok(list)
            },
            PatternKind::List(elements) => {
                let ty = self.unifier.fresh();
                for element in elements { let found = self.pattern(element, bindings)?; self.check(&ty, &found, element.position)?; }
                Ok(Type::list(ty))
            },
            PatternKind::Pair(a, b) => { let a = self.pattern(a, bindings)?; let b = self.pattern(b, bindings)?; Ok(Type::pair(a, b)) }
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct Position { pub file: usize, pub line: usize, pub column: usize }
#[derive(Clone)]
pub struct Token { pub kind: String, pub spelling: String, pub value: String, pub position: Position }
pub fn lex(text: &str, file: usize) -> Vec<Token> {
    let bytes = text.as_bytes();
    let mut positions = Vec::new();
    let (mut row, mut column) = (1, 1);
    for &c in bytes {
        positions.push(Position { file, line: row, column });
        if c == b'\n' { row += 1; column = 1; } else { column += 1; }
    }
    positions.push(Position { file, line: row, column });
    let mut tokens = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b' ' || bytes[i] == b'\n' { i += 1; continue; }
        let start = i;
        let mut kind: &str;
        let mut value = String::new();
        if text[i..].starts_with("(*") {
            if let Some(end) = text[i + 2..].find("*)") { i += end + 4; continue; }
            tokens.push(Token { kind: "invalid".into(), spelling: text[i..].into(), value: "unterminated comment".into(), position: positions[i] });
            break;
        } else if bytes[i].is_ascii_digit() {
            i += 1;
            while i < bytes.len() && bytes[i].is_ascii_digit() { i += 1; }
            if text[start..i].parse::<i64>().ok().map_or(false, |n| n <= 2147483647) {
                kind = "integer"; value = text[start..i].parse::<i64>().unwrap().to_string();
            } else { kind = "invalid"; value = "integer literal too large".into(); }
        } else if bytes[i].is_ascii_alphabetic() || bytes[i] == b'_' {
            i += 1;
            while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_' || bytes[i] == b'\'') { i += 1; }
            value = text[start..i].into();
            kind = if ["let", "rec", "and", "in", "fun", "if", "then", "else", "match", "with", "true", "false", "mod", "val"].contains(&value.as_str()) { "keyword" } else { "identifier" };
        } else if bytes[i] == b'\'' && i + 1 < bytes.len() && bytes[i + 1].is_ascii_lowercase() {
            i += 2;
            while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') { i += 1; }
            kind = "type_variable"; value = text[start..i].into();
        } else if bytes[i] == b'"' {
            i += 1;
            let (mut closed, mut valid) = (false, true);
            while i < bytes.len() && bytes[i] != b'\n' {
                if bytes[i] == b'"' { i += 1; closed = true; break; }
                if bytes[i] == b'\\' && i + 1 < bytes.len() && bytes[i + 1] != b'\n' {
                    match bytes[i + 1] { b'n' => value.push('\n'), b't' => value.push('\t'), b'\\' => value.push('\\'), b'"' => value.push('"'), _ => valid = false }
                    i += 2;
                } else if bytes[i] == b'\\' { i += 1; }
                else { value.push(bytes[i] as char); i += 1; }
            }
            if !closed { kind = "invalid"; value = "unterminated string".into(); }
            else if !valid { kind = "invalid"; value = "invalid escape sequence".into(); }
            else { kind = "string"; }
        } else {
            kind = "symbol";
            if i + 1 < bytes.len() && [";;", "->", "::", "||", "&&", "<=", ">=", "<>"].contains(&&text[i..i + 2]) { i += 2; }
            else if b":;=<>+-*/^()[],|".contains(&bytes[i]) { i += 1; }
            else { kind = "invalid"; value = format!("illegal character '{}'", bytes[i] as char); i += 1; }
            if kind == "symbol" { value = text[start..i].into(); }
        }
        tokens.push(Token { kind: kind.into(), spelling: text[start..i].into(), value, position: positions[start] });
    }
    tokens.push(Token { kind: "eof".into(), spelling: String::new(), value: String::new(), position: positions[bytes.len()] });
    tokens
}

mod lexer;
mod parser;
mod unifier;
mod inference;
mod evaluator;
use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use lexer::Position;
use parser::{Expression, ExprKind, Pattern, PatternKind, Group, Item, TypeExpression};
use unifier::{Type, Scheme, Unifier};
pub fn quote(value: &str) -> String {
    let mut out = String::from("\"");
    for c in value.chars() { match c { '\\' => out.push_str("\\\\"), '"' => out.push_str("\\\""), '\n' => out.push_str("\\n"), '\t' => out.push_str("\\t"), _ => out.push(c) } }
    out.push('"'); out
}
fn value_string(value: &evaluator::Value) -> String {
    use evaluator::Value;
    match value { Value::Integer(value) => value.to_string(), Value::Boolean(value) => value.to_string(), Value::String(value) => quote(value), Value::Pair(a, b) => format!("({}, {})", value_string(a), value_string(b)), Value::List(values) => format!("[{}]", values.iter().map(value_string).collect::<Vec<_>>().join("; ")), _ => "<fun>".into() }
}
pub fn edit_distance(a: &str, b: &str) -> usize {
    let mut row: Vec<_> = (0..=b.len()).collect();
    for (i, a) in a.bytes().enumerate() {
        let mut next = vec![i + 1];
        for (j, b) in b.bytes().enumerate() { next.push((next[j] + 1).min(row[j + 1] + 1).min(row[j] + usize::from(a != b))); }
        row = next;
    }
    row[b.len()]
}
struct TypePrinter<'a> { unifier: &'a Unifier, names: BTreeMap<usize, String>, quantified: Option<&'a BTreeSet<usize>> }
impl<'a> TypePrinter<'a> {
    fn new(unifier: &'a Unifier, quantified: Option<&'a BTreeSet<usize>>) -> Self { Self { unifier, names: BTreeMap::new(), quantified } }
    fn write(&mut self, ty: &Type) -> String {
        match self.unifier.resolve(ty) {
            Type::Integer => "int".into(), Type::Boolean => "bool".into(), Type::String => "string".into(),
            Type::Variable(index) => {
                if let Some(name) = self.names.get(&index) { return name.clone(); }
                let k = self.names.len();
                let suffix = if k >= 26 { (k / 26).to_string() } else { String::new() };
                let weak = self.quantified.map_or(false, |quantified| !quantified.contains(&index));
                let name = format!("'{}{}{}", if weak { "_" } else { "" }, (b'a' + (k % 26) as u8) as char, suffix);
                self.names.insert(index, name.clone()); name
            },
            Type::List(element) => { let written = self.write(&element); format!("{} list", if matches!(*element, Type::Pair(..) | Type::Function(..)) { format!("({})", written) } else { written }) },
            Type::Pair(a, b) => {
                let left = self.write(&a); let right = self.write(&b);
                format!("{} * {}", if matches!(*a, Type::Pair(..) | Type::Function(..)) { format!("({})", left) } else { left }, if matches!(*b, Type::Pair(..) | Type::Function(..)) { format!("({})", right) } else { right })
            },
            Type::Function(a, b) => { let left = self.write(&a); let right = self.write(&b); format!("{} -> {}", if matches!(*a, Type::Function(..)) { format!("({})", left) } else { left }, right) }
        }
    }
}
fn error_message(error: &inference::Error, unifier: &Unifier) -> String {
    use inference::ErrorKind;
    let mut printer = TypePrinter::new(unifier, None);
    match &error.kind {
        ErrorKind::Message(message) => message.clone(), ErrorKind::Function(ty) => format!("expected a function but found {}", printer.write(ty)),
        ErrorKind::Check(expected, found, failure) => {
            let mut message = format!("expected {} but found {}", printer.write(expected), printer.write(found));
            if failure.occurs {
                let (variable, other) = if matches!(failure.expected, Type::Variable(_)) { (&failure.expected, &failure.found) } else { (&failure.found, &failure.expected) };
                message.push_str(&format!(" (infinite type {} = {})", printer.write(variable), printer.write(other)));
            } else if failure.nested { message.push_str(&format!(" ({} vs {})", printer.write(&failure.expected), printer.write(&failure.found))); }
            message
        }
    }
}
fn signature_type(expression: &TypeExpression, unifier: &mut Unifier, variables: &mut BTreeMap<String, Type>) -> Type {
    match expression {
        TypeExpression::Primitive(name) => match name.as_str() { "int" => Type::Integer, "bool" => Type::Boolean, _ => Type::String },
        TypeExpression::Variable(name) => { if let Some(ty) = variables.get(name) { ty.clone() } else { let ty = unifier.fresh(); variables.insert(name.clone(), ty.clone()); ty } },
        TypeExpression::List(ty) => Type::list(signature_type(ty, unifier, variables)),
        TypeExpression::Pair(a, b) => { let a = signature_type(a, unifier, variables); let b = signature_type(b, unifier, variables); Type::pair(a, b) },
        TypeExpression::Function(a, b) => { let a = signature_type(a, unifier, variables); let b = signature_type(b, unifier, variables); Type::function(a, b) }
    }
}
fn signature_matches(inferred: &Type, declared: &Type, unifier: &Unifier, assigned: &mut BTreeMap<usize, Type>) -> bool {
    let inferred = unifier.resolve(inferred);
    let declared = unifier.resolve(declared);
    match inferred {
        Type::Variable(index) => if let Some(old) = assigned.get(&index) { *old == declared } else { assigned.insert(index, declared); true },
        Type::List(a) => if let Type::List(b) = declared { signature_matches(&a, &b, unifier, assigned) } else { false },
        Type::Pair(a, b) => if let Type::Pair(c, d) = declared { signature_matches(&a, &c, unifier, assigned) && signature_matches(&b, &d, unifier, assigned) } else { false },
        Type::Function(a, b) => if let Type::Function(c, d) = declared { signature_matches(&a, &c, unifier, assigned) && signature_matches(&b, &d, unifier, assigned) } else { false },
        _ => inferred == declared
    }
}
fn type_syntax(ty: &TypeExpression) -> String {
    match ty {
        TypeExpression::Primitive(name) | TypeExpression::Variable(name) => name.clone(),
        TypeExpression::List(ty) => { let value = type_syntax(ty); format!("{} list", if matches!(ty.as_ref(), TypeExpression::Pair(..) | TypeExpression::Function(..)) { format!("({})", value) } else { value }) },
        TypeExpression::Pair(a, b) => { let a_text = type_syntax(a); let b_text = type_syntax(b); format!("{} * {}", if matches!(a.as_ref(), TypeExpression::Pair(..) | TypeExpression::Function(..)) { format!("({})", a_text) } else { a_text }, if matches!(b.as_ref(), TypeExpression::Pair(..) | TypeExpression::Function(..)) { format!("({})", b_text) } else { b_text }) },
        TypeExpression::Function(a, b) => { let a_text = type_syntax(a); format!("{} -> {}", if matches!(a.as_ref(), TypeExpression::Function(..)) { format!("({})", a_text) } else { a_text }, type_syntax(b)) }
    }
}
fn pattern_string(pattern: &Pattern) -> String {
    match &pattern.kind {
        PatternKind::Wildcard => "_".into(), PatternKind::Name(name) => name.clone(), PatternKind::Integer(value) => value.to_string(), PatternKind::Boolean(value) => value.to_string(), PatternKind::String(value) => quote(value), PatternKind::Nil => "[]".into(),
        PatternKind::List(values) => format!("[{}]", values.iter().map(pattern_string).collect::<Vec<_>>().join("; ")),
        PatternKind::Pair(a, b) => format!("({}, {})", pattern_string(a), pattern_string(b)),
        PatternKind::Cons(a, b) => { let head = pattern_string(a); format!("{} :: {}", if matches!(&a.kind, PatternKind::Cons(..)) { format!("({})", head) } else { head }, pattern_string(b)) }
    }
}
fn group_string(group: &Group) -> String {
    let bindings: Vec<_> = group.bindings.iter().map(|binding| {
        let mut body = binding.expression.clone(); let mut names = vec![binding.name.clone()];
        while let ExprKind::Fun(parameter, next) = &body.kind { names.push(parameter.name.clone().unwrap_or_else(|| "_".into())); body = next.clone(); }
        format!("{} = {}", names.join(" "), expression_string(&body, 0))
    }).collect();
    format!("let {}{}", if group.recursive.is_some() { "rec " } else { "" }, bindings.join(" and "))
}
fn ends_in_match(expression: &Expression) -> bool {
    match &expression.kind { ExprKind::Match(..) => true, ExprKind::Let(_, body) | ExprKind::Fun(_, body) => ends_in_match(body), ExprKind::If(_, _, no) => ends_in_match(no), _ => false }
}
fn expression_string(expression: &Expression, required: usize) -> String {
    let (strength, text) = match &expression.kind {
        ExprKind::Integer(value) => (9, value.to_string()), ExprKind::Boolean(value) => (9, value.to_string()), ExprKind::String(value) => (9, quote(value)), ExprKind::Name(name) => (9, name.clone()),
        ExprKind::Fun(..) => {
            let mut body = expression.clone(); let mut parameters = Vec::new();
            while let ExprKind::Fun(parameter, next) = &body.kind { parameters.push(parameter.name.clone().unwrap_or_else(|| "_".into())); body = next.clone(); }
            (0, format!("fun {} -> {}", parameters.join(" "), expression_string(&body, 0)))
        },
        ExprKind::Apply(function, argument) => (8, format!("{} {}", expression_string(function, 8), expression_string(argument, 9))),
        ExprKind::Binary(operator, _, left, right) => { let p = parser::precedence(operator); let right_associative = parser::right_associative(operator); (p, format!("{} {} {}", expression_string(left, p + usize::from(right_associative)), operator, expression_string(right, p + usize::from(!right_associative)))) },
        ExprKind::Negate(_, value) => (7, format!("-{}", expression_string(value, 7))),
        ExprKind::If(condition, yes, no) => (0, format!("if {} then {} else {}", expression_string(condition, 0), expression_string(yes, 0), expression_string(no, 0))),
        ExprKind::Pair(a, b) => (9, format!("({}, {})", expression_string(a, 0), expression_string(b, 0))),
        ExprKind::List(values) => (9, format!("[{}]", values.iter().map(|value| expression_string(value, 0)).collect::<Vec<_>>().join("; "))),
        ExprKind::Let(group, body) => (0, format!("{} in {}", group_string(group), expression_string(body, 0))),
        ExprKind::Match(value, arms) => {
            let arms: Vec<_> = arms.iter().enumerate().map(|(i, (pattern, body))| { let body_text = expression_string(body, 0); format!("{} -> {}", pattern_string(pattern), if i + 1 < arms.len() && ends_in_match(body) { format!("({})", body_text) } else { body_text }) }).collect();
            (0, format!("match {} with {}", expression_string(value, 0), arms.join(" | ")))
        }
    };
    if strength < required { format!("({})", text) } else { text }
}
fn item_string(item: &Item) -> String { match item { Item::Signature(name, _, ty) => format!("val {} : {};;", name, type_syntax(ty)), Item::Declaration(group) => format!("{};;", group_string(group)), Item::Expression(expression) => format!("{};;", expression_string(expression, 0)) } }

#[derive(Clone)]
enum Cover { Wild, Constructor(String, Vec<Cover>) }
fn cover(pattern: &Pattern) -> Cover {
    fn list(values: &[Pattern]) -> Cover {
        if values.is_empty() { Cover::Constructor("nil".into(), Vec::new()) }
        else { Cover::Constructor("cons".into(), vec![cover(&values[0]), list(&values[1..])]) }
    }
    match &pattern.kind {
        PatternKind::Wildcard | PatternKind::Name(_) => Cover::Wild,
        PatternKind::Integer(value) => Cover::Constructor(format!("i{}", value), Vec::new()),
        PatternKind::String(value) => Cover::Constructor(format!("s{}", quote(value)), Vec::new()),
        PatternKind::Boolean(value) => Cover::Constructor(value.to_string(), Vec::new()),
        PatternKind::Nil => Cover::Constructor("nil".into(), Vec::new()),
        PatternKind::Cons(a, b) => Cover::Constructor("cons".into(), vec![cover(a), cover(b)]),
        PatternKind::Pair(a, b) => Cover::Constructor("pair".into(), vec![cover(a), cover(b)]),
        PatternKind::List(values) => list(values)
    }
}
fn constructor_arguments(ty: &Type, name: &str) -> Vec<Type> {
    match ty { Type::List(element) if name == "cons" => vec![element.as_ref().clone(), ty.clone()], Type::Pair(a, b) => vec![a.as_ref().clone(), b.as_ref().clone()], _ => Vec::new() }
}
fn specialize(matrix: &[Vec<Cover>], name: &str, arity: usize) -> Vec<Vec<Cover>> {
    let mut result = Vec::new();
    for row in matrix {
        let prefix = match &row[0] { Cover::Wild => vec![Cover::Wild; arity], Cover::Constructor(constructor, arguments) if constructor == name => arguments.clone(), _ => continue };
        let mut next = prefix; next.extend_from_slice(&row[1..]); result.push(next);
    }
    result
}
fn useful(matrix: &[Vec<Cover>], vector: &[Cover], types: &[Type]) -> bool {
    if vector.is_empty() { return matrix.is_empty(); }
    if let Cover::Constructor(name, arguments) = &vector[0] {
        let mut next = arguments.clone(); next.extend_from_slice(&vector[1..]);
        let mut next_types = constructor_arguments(&types[0], name); next_types.extend_from_slice(&types[1..]);
        return useful(&specialize(matrix, name, arguments.len()), &next, &next_types);
    }
    let family: Vec<&str> = match &types[0] { Type::Boolean => vec!["false", "true"], Type::List(_) => vec!["nil", "cons"], Type::Pair(..) => vec!["pair"], _ => Vec::new() };
    let present: BTreeSet<_> = matrix.iter().filter_map(|row| if let Cover::Constructor(name, _) = &row[0] { Some(name.as_str()) } else { None }).collect();
    if !family.is_empty() && family.iter().all(|name| present.contains(name)) {
        for name in family {
            let mut arguments = constructor_arguments(&types[0], name);
            let arity = arguments.len(); arguments.extend_from_slice(&types[1..]);
            let mut next = vec![Cover::Wild; arity]; next.extend_from_slice(&vector[1..]);
            if useful(&specialize(matrix, name, arity), &next, &arguments) { return true; }
        }
        false
    } else {
        let defaults: Vec<_> = matrix.iter().filter(|row| matches!(row[0], Cover::Wild)).map(|row| row[1..].to_vec()).collect();
        useful(&defaults, &vector[1..], &types[1..])
    }
}
type Scope = BTreeMap<String, Position>;
#[derive(Clone)]
struct Reference { target: Position, tail: bool }
fn pattern_names(pattern: &Pattern) -> Vec<(String, Position)> {
    match &pattern.kind {
        PatternKind::Name(name) => vec![(name.clone(), pattern.position)],
        PatternKind::Cons(a, b) | PatternKind::Pair(a, b) => { let mut names = pattern_names(a); names.extend(pattern_names(b)); names },
        PatternKind::List(values) => values.iter().flat_map(pattern_names).collect(),
        _ => Vec::new()
    }
}
fn pure_references(expression: &Expression, scope: &Scope, tail: bool) -> Vec<Reference> {
    match &expression.kind {
        ExprKind::Name(name) => scope.get(name).map_or_else(Vec::new, |&target| vec![Reference { target, tail: false }]),
        ExprKind::Fun(parameter, body) => { let mut inner = scope.clone(); if let Some(name) = &parameter.name { inner.insert(name.clone(), parameter.position); } pure_references(body, &inner, false) },
        ExprKind::Apply(..) => {
            let mut head = expression.clone(); let mut arguments = Vec::new();
            while let ExprKind::Apply(function, argument) = &head.kind { arguments.push(argument.clone()); head = function.clone(); }
            arguments.reverse();
            let mut references = if let ExprKind::Name(name) = &head.kind { scope.get(name).map_or_else(Vec::new, |&target| vec![Reference { target, tail }]) } else { pure_references(&head, scope, false) };
            for argument in arguments { references.extend(pure_references(&argument, scope, false)); }
            references
        },
        ExprKind::Binary(operator, _, a, b) => { let mut references = pure_references(a, scope, false); references.extend(pure_references(b, scope, tail && (operator == "&&" || operator == "||"))); references },
        ExprKind::Negate(_, body) => pure_references(body, scope, false),
        ExprKind::If(condition, yes, no) => { let mut references = pure_references(condition, scope, false); references.extend(pure_references(yes, scope, tail)); references.extend(pure_references(no, scope, tail)); references },
        ExprKind::Pair(a, b) => { let mut references = pure_references(a, scope, false); references.extend(pure_references(b, scope, false)); references },
        ExprKind::List(values) => values.iter().flat_map(|value| pure_references(value, scope, false)).collect(),
        ExprKind::Match(value, arms) => {
            let mut references = pure_references(value, scope, false);
            for (pattern, body) in arms { let mut inner = scope.clone(); inner.extend(pattern_names(pattern)); references.extend(pure_references(body, &inner, tail)); }
            references
        },
        ExprKind::Let(group, body) => {
            let mut inner = scope.clone(); for binding in &group.bindings { inner.insert(binding.name.clone(), binding.position); }
            let rhs_scope = if group.recursive.is_some() { &inner } else { scope };
            let mut references: Vec<_> = group.bindings.iter().flat_map(|binding| pure_references(&binding.expression, rhs_scope, false)).collect();
            references.extend(pure_references(body, &inner, tail)); references
        },
        _ => Vec::new()
    }
}
struct Inspection { warnings: Vec<(Position, usize, String)>, classifications: BTreeMap<Position, &'static str>, candidates: BTreeMap<Position, String> }
impl Inspection {
    fn new() -> Self { Self { warnings: Vec::new(), classifications: BTreeMap::new(), candidates: BTreeMap::new() } }
    fn group(&mut self, group: &Group, scope: &Scope, top: bool, context: &inference::Context) -> Scope {
        let mut inner = scope.clone();
        for binding in &group.bindings {
            inner.insert(binding.name.clone(), binding.position);
            if !top { self.candidates.insert(binding.position, binding.name.clone()); }
        }
        let rhs_scope = if group.recursive.is_some() { &inner } else { scope };
        for binding in &group.bindings { self.walk(&binding.expression, rhs_scope, context); }
        if let Some(position) = group.recursive {
            let names: BTreeSet<_> = group.bindings.iter().map(|binding| binding.position).collect();
            let references: Vec<_> = group.bindings.iter().flat_map(|binding| pure_references(&binding.expression, &inner, false)).collect();
            if references.iter().all(|reference| !names.contains(&reference.target)) { self.warnings.push((position, 3, "unused rec flag".into())); }
            for binding in &group.bindings {
                let mut body = binding.expression.clone(); let mut body_scope = inner.clone();
                while let ExprKind::Fun(parameter, next) = &body.kind { if let Some(name) = &parameter.name { body_scope.insert(name.clone(), parameter.position); } body = next.clone(); }
                let references: Vec<_> = pure_references(&body, &body_scope, true).into_iter().filter(|reference| names.contains(&reference.target)).collect();
                if !references.is_empty() { self.classifications.insert(binding.position, if references.iter().all(|reference| reference.tail) { "tail recursive" } else { "recursive" }); }
            }
        }
        inner
    }
    fn walk(&mut self, expression: &Expression, scope: &Scope, context: &inference::Context) {
        match &expression.kind {
            ExprKind::Fun(parameter, body) => {
                let mut inner = scope.clone();
                if let Some(name) = &parameter.name { self.candidates.insert(parameter.position, name.clone()); inner.insert(name.clone(), parameter.position); }
                self.walk(body, &inner, context);
            },
            ExprKind::Apply(a, b) | ExprKind::Pair(a, b) | ExprKind::Binary(_, _, a, b) => { self.walk(a, scope, context); self.walk(b, scope, context); },
            ExprKind::Negate(_, body) => self.walk(body, scope, context),
            ExprKind::If(condition, yes, no) => { self.walk(condition, scope, context); self.walk(yes, scope, context); self.walk(no, scope, context); },
            ExprKind::List(values) => { for value in values { self.walk(value, scope, context); } },
            ExprKind::Let(group, body) => { let inner = self.group(group, scope, false, context); self.walk(body, &inner, context); },
            ExprKind::Match(value, arms) => {
                let (ty, patterns) = &context.matches[&expression.position];
                let ty = context.unifier.resolve(ty);
                let mut matrix = Vec::new();
                for (i, pattern) in patterns.iter().enumerate() {
                    let candidate = cover(pattern);
                    if i > 0 && !useful(&matrix, &[candidate.clone()], &[ty.clone()]) { self.warnings.push((pattern.position, 2, "this match case is unused".into())); }
                    matrix.push(vec![candidate]);
                }
                if useful(&matrix, &[Cover::Wild], &[ty]) { self.warnings.push((expression.position, 1, "this match is not exhaustive".into())); }
                self.walk(value, scope, context);
                for (pattern, body) in arms {
                    let mut inner = scope.clone();
                    for (name, position) in pattern_names(pattern) { self.candidates.insert(position, name.clone()); inner.insert(name, position); }
                    self.walk(body, &inner, context);
                }
            },
            _ => ()
        }
    }
    fn finish(&mut self, references: Vec<Reference>) {
        let used: BTreeSet<_> = references.into_iter().map(|reference| reference.target).collect();
        for (&position, name) in &self.candidates { if !name.starts_with('_') && !used.contains(&position) { self.warnings.push((position, 4, format!("unused variable '{}'", name))); } }
        self.warnings.sort_by_key(|warning| (warning.0, warning.1));
    }
}
fn inspection(item: &Item, scope: &Scope, context: &inference::Context) -> Inspection {
    let mut inspection = Inspection::new();
    let references = match item {
        Item::Declaration(group) => { let inner = inspection.group(group, scope, true, context); group.bindings.iter().flat_map(|binding| pure_references(&binding.expression, if group.recursive.is_some() { &inner } else { scope }, false)).collect() },
        Item::Expression(expression) => { inspection.walk(expression, scope, context); pure_references(expression, scope, false) },
        _ => Vec::new()
    };
    inspection.finish(references); inspection
}

fn builtins(unifier: &mut Unifier) -> (unifier::Environment, evaluator::Environment) {
    let mut types = BTreeMap::new();
    let a = unifier.fresh(); let b = unifier.fresh();
    let fst = Type::function(Type::pair(a.clone(), b), a);
    types.insert("fst".into(), Scheme { quantified: unifier.variables(&fst), ty: fst });
    let a = unifier.fresh(); let b = unifier.fresh();
    let snd = Type::function(Type::pair(a, b.clone()), b);
    types.insert("snd".into(), Scheme { quantified: unifier.variables(&snd), ty: snd });
    types.insert("not".into(), Scheme::mono(Type::function(Type::Boolean, Type::Boolean)));
    types.insert("string_of_int".into(), Scheme::mono(Type::function(Type::Integer, Type::String)));
    let result = unifier.fresh();
    let failwith = Type::function(Type::String, result);
    types.insert("failwith".into(), Scheme { quantified: unifier.variables(&failwith), ty: failwith });
    let values = ["fst", "snd", "not", "string_of_int", "failwith"].iter().map(|name| (name.to_string(), evaluator::Value::Builtin(name.to_string()))).collect();
    (types, values)
}
#[derive(Clone)]
struct Signature { position: Position, ty: TypeExpression }
fn report(position: Position, kind: &str, message: &str, sources: &[Vec<String>], output: &mut Vec<String>) {
    let name = ["prelude.ml", "program.ml"][position.file];
    output.push(format!("{}:{}:{}: {}: {}", name, position.line, position.column, kind, message));
    if position.line <= sources[position.file].len() {
        output.push(format!("    {}", sources[position.file][position.line - 1]));
        output.push(format!("{}^", " ".repeat(position.column + 3)));
    }
}
fn write(name: &str, lines: &[String]) {
    fs::create_dir_all("output").unwrap();
    fs::write(format!("output/{}", name), if lines.is_empty() { String::new() } else { lines.join("\n") + "\n" }).unwrap();
}
fn main() {
    let file_names = ["prelude.ml", "program.ml"];
    let texts: Vec<_> = file_names.iter().map(|name| fs::read_to_string(format!("input/{}", name)).unwrap()).collect();
    let sources: Vec<Vec<String>> = texts.iter().map(|text| text.lines().map(str::to_string).collect()).collect();
    let mut context = inference::Context::new();
    let (mut type_environment, mut value_environment) = builtins(&mut context.unifier);
    let mut evaluator = evaluator::Evaluator { calls: 0 };
    let mut scope = Scope::new();
    let (mut types, mut values, mut errors, mut formatted) = (Vec::new(), Vec::new(), Vec::new(), Vec::new());
    let mut statistics = [[0usize; 7]; 2];
    for file in 0..2 {
        types.push(format!("== {} ==", file_names[file])); values.push(format!("== {} ==", file_names[file])); formatted.push(format!("(* {} *)", file_names[file]));
        let mut pending: BTreeMap<String, Signature> = BTreeMap::new();
        let mut parser = parser::Parser { tokens: lexer::lex(&texts[file], file), index: 0 };
        evaluator.calls = 0;
        while parser.peek().kind != "eof" {
            statistics[file][0] += 1;
            let item = match parser.item() {
                Ok(item) => item,
                Err(token) => {
                    let message = if token.kind == "invalid" { token.value.clone() } else if token.kind == "eof" { "unexpected end of file".into() } else { format!("unexpected '{}'", token.spelling) };
                    statistics[file][2] += 1; report(token.position, "syntax error", &message, &sources, &mut errors);
                    parser.recover(); continue;
                }
            };
            formatted.push(item_string(&item));
            if let Item::Signature(name, position, ty) = &item {
                if let Some(old) = pending.insert(name.clone(), Signature { position: *position, ty: ty.clone() }) {
                    statistics[file][5] += 1; report(old.position, "warning", &format!("signature for '{}' is never used", name), &sources, &mut errors);
                }
                continue;
            }
            context.clear();
            let typing = (|| -> Result<(unifier::Environment, Vec<Scheme>, Option<Type>), (Position, String)> {
                match &item {
                    Item::Declaration(group) => {
                        let signatures: Vec<_> = group.bindings.iter().map(|binding| pending.remove(&binding.name)).collect();
                        let (mut next, mut schemes) = context.group(group, &type_environment, false).map_err(|error| (error.position, error_message(&error, &context.unifier)))?;
                        for (i, signature) in signatures.iter().enumerate() {
                            if let Some(signature) = signature {
                                let declared = signature_type(&signature.ty, &mut context.unifier, &mut BTreeMap::new());
                                if !signature_matches(&schemes[i].ty, &declared, &context.unifier, &mut BTreeMap::new()) {
                                    let mut printer = TypePrinter::new(&context.unifier, None);
                                    return Err((group.bindings[i].position, format!("'{}' has type {} but its signature is {}", group.bindings[i].name, printer.write(&schemes[i].ty), printer.write(&declared))));
                                }
                                schemes[i] = Scheme { quantified: context.unifier.variables(&declared), ty: declared };
                                next.insert(group.bindings[i].name.clone(), schemes[i].clone());
                            }
                        }
                        Ok((next, schemes, None))
                    },
                    Item::Expression(expression) => {
                        let ty = context.expression(expression, &type_environment).map_err(|error| (error.position, error_message(&error, &context.unifier)))?;
                        Ok((type_environment.clone(), Vec::new(), Some(ty)))
                    },
                    _ => unreachable!()
                }
            })();
            let (next_types, schemes, expression_type) = match typing {
                Ok(result) => result,
                Err((position, message)) => { statistics[file][3] += 1; report(position, "type error", &message, &sources, &mut errors); continue; }
            };
            let inspected = inspection(&item, &scope, &context);
            let classification = |position: Position| inspected.classifications.get(&position).map_or_else(String::new, |kind| format!(" ({})", kind));
            if let Item::Declaration(group) = &item {
                for (binding, scheme) in group.bindings.iter().zip(&schemes) {
                    let ty = TypePrinter::new(&context.unifier, None).write(&scheme.ty);
                    types.push(format!("{} : {}{}", binding.name, ty, classification(binding.position)));
                }
            } else { types.push(format!("- : {}", TypePrinter::new(&context.unifier, None).write(expression_type.as_ref().unwrap()))); }
            context.locals.sort_by_key(|local| local.position);
            for local in &context.locals {
                let ty = TypePrinter::new(&context.unifier, Some(&local.scheme.quantified)).write(&local.scheme.ty);
                types.push(format!("  {} ({}:{}) : {}{}", local.name, local.position.line, local.position.column, ty, classification(local.position)));
            }
            for (position, _, message) in &inspected.warnings { statistics[file][5] += 1; report(*position, "warning", message, &sources, &mut errors); }
            let evaluated = match &item {
                Item::Declaration(group) => evaluator.group(group, &value_environment),
                Item::Expression(expression) => evaluator.expression(expression, &value_environment).map(|value| (value_environment.clone(), vec![value])),
                _ => unreachable!()
            };
            let (next_values, evaluated) = match evaluated {
                Ok(result) => result,
                Err(error) => { statistics[file][4] += 1; report(error.position, "runtime error", &error.message, &sources, &mut errors); continue; }
            };
            if let Item::Declaration(group) = &item {
                for (binding, value) in group.bindings.iter().zip(&evaluated) {
                    values.push(format!("{} = {}", binding.name, value_string(value)));
                    scope.insert(binding.name.clone(), binding.position);
                }
                statistics[file][1] += group.bindings.len();
            } else { values.push(format!("- = {}", value_string(&evaluated[0]))); }
            type_environment = next_types; value_environment = next_values;
        }
        let mut unused: Vec<_> = pending.into_iter().collect(); unused.sort_by_key(|(_, signature)| signature.position);
        for (name, signature) in unused { statistics[file][5] += 1; report(signature.position, "warning", &format!("signature for '{}' is never used", name), &sources, &mut errors); }
        statistics[file][6] = evaluator.calls;
    }
    errors.push("== summary ==".into());
    for file in 0..2 { let s = statistics[file]; errors.push(format!("{}: items={} bindings={} syntax={} type={} runtime={} warnings={} calls={}", file_names[file], s[0], s[1], s[2], s[3], s[4], s[5], s[6])); }
    write("types.txt", &types); write("values.txt", &values); write("errors.txt", &errors); write("formatted.ml", &formatted);
}

use std::rc::Rc;
use crate::lexer::{Position, Token};
pub type Expression = Rc<Expr>;
#[derive(Clone)]
pub struct Expr { pub position: Position, pub kind: ExprKind }
#[derive(Clone)]
pub enum ExprKind {
    Integer(i64), Boolean(bool), String(String), Name(String), Fun(Parameter, Expression),
    Apply(Expression, Expression), Binary(String, Position, Expression, Expression), Negate(Position, Expression),
    If(Expression, Expression, Expression), Pair(Expression, Expression), List(Vec<Expression>),
    Match(Expression, Vec<(Pattern, Expression)>), Let(Group, Expression)
}
#[derive(Clone)]
pub struct Parameter { pub name: Option<String>, pub position: Position }
#[derive(Clone)]
pub struct Binding { pub name: String, pub position: Position, pub expression: Expression }
#[derive(Clone)]
pub struct Group { pub recursive: Option<Position>, pub bindings: Vec<Binding> }
#[derive(Clone)]
pub struct Pattern { pub position: Position, pub kind: PatternKind }
#[derive(Clone)]
pub enum PatternKind { Wildcard, Name(String), Integer(i64), Boolean(bool), String(String), Nil, Cons(Box<Pattern>, Box<Pattern>), List(Vec<Pattern>), Pair(Box<Pattern>, Box<Pattern>) }
#[derive(Clone)]
pub enum TypeExpression { Primitive(String), Variable(String), List(Box<TypeExpression>), Pair(Box<TypeExpression>, Box<TypeExpression>), Function(Box<TypeExpression>, Box<TypeExpression>) }
#[derive(Clone)]
pub enum Item { Signature(String, Position, TypeExpression), Declaration(Group), Expression(Expression) }
pub fn precedence(op: &str) -> usize { match op { "||" => 1, "&&" => 2, "=" | "<>" | "<" | ">" | "<=" | ">=" => 3, "::" | "^" => 4, "+" | "-" => 5, "*" | "/" | "mod" => 6, _ => 0 } }
pub fn right_associative(op: &str) -> bool { ["||", "&&", "::", "^"].contains(&op) }
fn expression(position: Position, kind: ExprKind) -> Expression { Rc::new(Expr { position, kind }) }
pub struct Parser { pub tokens: Vec<Token>, pub index: usize }
impl Parser {
    pub fn peek(&self) -> &Token { &self.tokens[self.index] }
    fn spelling(&self) -> &str { &self.peek().value }
    fn take(&mut self) -> Token { let token = self.peek().clone(); if token.kind != "eof" { self.index += 1; } token }
    fn expect(&mut self, word: &str) -> Result<Token, Token> { if self.spelling() == word && self.peek().kind != "invalid" { Ok(self.take()) } else { Err(self.peek().clone()) } }
    fn name(&mut self) -> Result<Token, Token> { if self.peek().kind == "identifier" && self.spelling() != "_" { Ok(self.take()) } else { Err(self.peek().clone()) } }
    fn parameter(&mut self) -> Result<Parameter, Token> {
        if self.peek().kind != "identifier" { return Err(self.peek().clone()); }
        let token = self.take();
        Ok(Parameter { name: if token.value == "_" { None } else { Some(token.value) }, position: token.position })
    }
    fn atomic_start(&self) -> bool { let token = self.peek(); ["integer", "string"].contains(&token.kind.as_str()) || token.kind == "identifier" && token.value != "_" || token.kind != "invalid" && ["true", "false", "(", "["].contains(&token.value.as_str()) }
    fn group(&mut self) -> Result<Group, Token> {
        self.expect("let")?;
        let recursive = if self.spelling() == "rec" { Some(self.take().position) } else { None };
        let mut bindings = Vec::new();
        loop {
            let name = self.name()?;
            let mut parameters = Vec::new();
            while self.peek().kind == "identifier" { parameters.push(self.parameter()?); }
            self.expect("=")?;
            let mut body = self.expr()?;
            for parameter in parameters.into_iter().rev() { body = expression(parameter.position, ExprKind::Fun(parameter, body)); }
            bindings.push(Binding { name: name.value, position: name.position, expression: body });
            if self.spelling() != "and" { break; }
            self.take();
        }
        Ok(Group { recursive, bindings })
    }
    pub fn item(&mut self) -> Result<Item, Token> {
        let item = if self.spelling() == "val" {
            self.take(); let name = self.name()?; self.expect(":")?;
            Item::Signature(name.value, name.position, self.type_expression()?)
        } else if self.spelling() == "let" {
            let position = self.peek().position;
            let group = self.group()?;
            if self.spelling() == "in" { self.take(); Item::Expression(expression(position, ExprKind::Let(group, self.expr()?))) }
            else { Item::Declaration(group) }
        } else { Item::Expression(self.expr()?) };
        self.expect(";;")?;
        Ok(item)
    }
    fn expr(&mut self) -> Result<Expression, Token> {
        let position = self.peek().position;
        match self.spelling() {
            "let" => { let group = self.group()?; self.expect("in")?; Ok(expression(position, ExprKind::Let(group, self.expr()?))) },
            "fun" => {
                self.take(); let mut parameters = vec![self.parameter()?];
                while self.peek().kind == "identifier" { parameters.push(self.parameter()?); }
                self.expect("->")?;
                let mut body = self.expr()?;
                for (i, parameter) in parameters.into_iter().enumerate().collect::<Vec<_>>().into_iter().rev() {
                    let start = if i == 0 { position } else { parameter.position };
                    body = expression(start, ExprKind::Fun(parameter, body));
                }
                Ok(body)
            },
            "if" => {
                self.take(); let condition = self.expr()?; self.expect("then")?;
                let yes = self.expr()?; self.expect("else")?; let no = self.expr()?;
                Ok(expression(position, ExprKind::If(condition, yes, no)))
            },
            "match" => {
                self.take(); let value = self.expr()?; self.expect("with")?;
                if self.spelling() == "|" { self.take(); }
                let mut arms = Vec::new();
                loop {
                    let pattern = self.pattern()?; self.expect("->")?; let body = self.expr()?;
                    arms.push((pattern, body));
                    if self.spelling() != "|" { break; }
                    self.take();
                }
                Ok(expression(position, ExprKind::Match(value, arms)))
            },
            _ => self.binary(1)
        }
    }
    fn binary(&mut self, minimum: usize) -> Result<Expression, Token> {
        let mut left = self.unary()?;
        loop {
            let priority = precedence(self.spelling());
            if priority < minimum || priority == 0 { break; }
            let operator = self.take();
            let right = self.binary(if right_associative(&operator.value) { priority } else { priority + 1 })?;
            left = expression(left.position, ExprKind::Binary(operator.value, operator.position, left, right));
        }
        Ok(left)
    }
    fn unary(&mut self) -> Result<Expression, Token> {
        if self.spelling() == "-" { let token = self.take(); return Ok(expression(token.position, ExprKind::Negate(token.position, self.unary()?))); }
        let mut function = self.atomic()?;
        while self.atomic_start() { let argument = self.atomic()?; function = expression(function.position, ExprKind::Apply(function, argument)); }
        Ok(function)
    }
    fn atomic(&mut self) -> Result<Expression, Token> {
        let token = self.peek().clone();
        let position = token.position;
        let kind = match token.kind.as_str() {
            "integer" => { self.take(); ExprKind::Integer(token.value.parse().unwrap()) },
            "string" => { self.take(); ExprKind::String(token.value) },
            "identifier" if token.value != "_" => { self.take(); ExprKind::Name(token.value) },
            _ => match token.value.as_str() {
                "true" | "false" if token.kind != "invalid" => { self.take(); ExprKind::Boolean(token.value == "true") },
                "(" if token.kind != "invalid" => {
                    self.take(); let first = self.expr()?;
                    if self.spelling() == "," { self.take(); let second = self.expr()?; self.expect(")")?; ExprKind::Pair(first, second) }
                    else { self.expect(")")?; return Ok(first); }
                },
                "[" if token.kind != "invalid" => {
                    self.take(); let mut elements = Vec::new();
                    if self.spelling() != "]" {
                        elements.push(self.expr()?);
                        while self.spelling() == ";" { self.take(); elements.push(self.expr()?); }
                    }
                    self.expect("]")?; ExprKind::List(elements)
                },
                _ => return Err(token)
            }
        };
        Ok(expression(position, kind))
    }
    fn pattern(&mut self) -> Result<Pattern, Token> {
        let head = self.atomic_pattern()?;
        if self.spelling() == "::" { self.take(); let tail = self.pattern()?; Ok(Pattern { position: head.position, kind: PatternKind::Cons(Box::new(head), Box::new(tail)) }) }
        else { Ok(head) }
    }
    fn atomic_pattern(&mut self) -> Result<Pattern, Token> {
        let token = self.peek().clone();
        let position = token.position;
        let kind = match token.kind.as_str() {
            "integer" => { self.take(); PatternKind::Integer(token.value.parse().unwrap()) },
            "string" => { self.take(); PatternKind::String(token.value) },
            "identifier" => { self.take(); if token.value == "_" { PatternKind::Wildcard } else { PatternKind::Name(token.value) } },
            _ => match token.value.as_str() {
                "true" | "false" if token.kind != "invalid" => { self.take(); PatternKind::Boolean(token.value == "true") },
                "-" if token.kind != "invalid" => { self.take(); if self.peek().kind != "integer" { return Err(self.peek().clone()); } PatternKind::Integer(-self.take().value.parse::<i64>().unwrap()) },
                "(" if token.kind != "invalid" => {
                    self.take(); let first = self.pattern()?;
                    if self.spelling() == "," { self.take(); let second = self.pattern()?; self.expect(")")?; PatternKind::Pair(Box::new(first), Box::new(second)) }
                    else { self.expect(")")?; return Ok(first); }
                },
                "[" if token.kind != "invalid" => {
                    self.take(); let mut elements = Vec::new();
                    if self.spelling() != "]" { elements.push(self.pattern()?); while self.spelling() == ";" { self.take(); elements.push(self.pattern()?); } }
                    self.expect("]")?;
                    if elements.is_empty() { PatternKind::Nil } else { PatternKind::List(elements) }
                },
                _ => return Err(token)
            }
        };
        Ok(Pattern { position, kind })
    }
    fn type_expression(&mut self) -> Result<TypeExpression, Token> {
        let first = self.product_type()?;
        if self.spelling() == "->" { self.take(); Ok(TypeExpression::Function(Box::new(first), Box::new(self.type_expression()?))) }
        else { Ok(first) }
    }
    fn product_type(&mut self) -> Result<TypeExpression, Token> {
        let first = self.list_type()?;
        if self.spelling() == "*" { self.take(); Ok(TypeExpression::Pair(Box::new(first), Box::new(self.list_type()?))) }
        else { Ok(first) }
    }
    fn list_type(&mut self) -> Result<TypeExpression, Token> {
        let mut ty = self.type_atom()?;
        while self.peek().kind == "identifier" && self.spelling() == "list" { self.take(); ty = TypeExpression::List(Box::new(ty)); }
        Ok(ty)
    }
    fn type_atom(&mut self) -> Result<TypeExpression, Token> {
        let token = self.peek().clone();
        if token.kind == "type_variable" { self.take(); Ok(TypeExpression::Variable(token.value)) }
        else if token.kind == "identifier" && ["int", "bool", "string"].contains(&token.value.as_str()) { self.take(); Ok(TypeExpression::Primitive(token.value)) }
        else if token.kind == "symbol" && token.value == "(" { self.take(); let ty = self.type_expression()?; self.expect(")")?; Ok(ty) }
        else { Err(token) }
    }
    pub fn recover(&mut self) { while self.peek().kind != "eof" && self.spelling() != ";;" { self.take(); } if self.spelling() == ";;" { self.take(); } }
}

use std::collections::{BTreeMap, BTreeSet};
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Type { Integer, Boolean, String, Variable(usize), List(Box<Type>), Pair(Box<Type>, Box<Type>), Function(Box<Type>, Box<Type>) }
impl Type {
    pub fn list(ty: Type) -> Self { Self::List(Box::new(ty)) }
    pub fn pair(a: Type, b: Type) -> Self { Self::Pair(Box::new(a), Box::new(b)) }
    pub fn function(a: Type, b: Type) -> Self { Self::Function(Box::new(a), Box::new(b)) }
}
#[derive(Clone)]
pub struct Scheme { pub ty: Type, pub quantified: BTreeSet<usize> }
impl Scheme { pub fn mono(ty: Type) -> Self { Self { ty, quantified: BTreeSet::new() } } }
pub type Environment = BTreeMap<String, Scheme>;
#[derive(Clone)]
pub struct Failure { pub expected: Type, pub found: Type, pub occurs: bool, pub nested: bool }
pub struct Unifier { bindings: Vec<Option<Type>> }
impl Unifier {
    pub fn new() -> Self { Self { bindings: Vec::new() } }
    pub fn fresh(&mut self) -> Type { let index = self.bindings.len(); self.bindings.push(None); Type::Variable(index) }
    pub fn resolve(&self, ty: &Type) -> Type {
        match ty {
            Type::Variable(index) => if let Some(ty) = &self.bindings[*index] { self.resolve(ty) } else { ty.clone() },
            Type::List(ty) => Type::list(self.resolve(ty)),
            Type::Pair(a, b) => Type::pair(self.resolve(a), self.resolve(b)),
            Type::Function(a, b) => Type::function(self.resolve(a), self.resolve(b)),
            _ => ty.clone()
        }
    }
    pub fn variables(&self, ty: &Type) -> BTreeSet<usize> {
        fn collect(ty: &Type, out: &mut BTreeSet<usize>) {
            match ty { Type::Variable(i) => { out.insert(*i); }, Type::List(ty) => collect(ty, out), Type::Pair(a, b) | Type::Function(a, b) => { collect(a, out); collect(b, out); }, _ => () }
        }
        let mut out = BTreeSet::new(); collect(&self.resolve(ty), &mut out); out
    }
    pub fn bind(&mut self, index: usize, ty: Type) { self.bindings[index] = Some(ty); }
    pub fn unify(&mut self, expected: &Type, found: &Type) -> Result<(), Failure> { self.unify_at(expected, found, false) }
    fn unify_at(&mut self, expected: &Type, found: &Type, nested: bool) -> Result<(), Failure> {
        let expected = self.resolve(expected);
        let found = self.resolve(found);
        if expected == found { return Ok(()); }
        if let Type::Variable(index) = expected {
            if self.variables(&found).contains(&index) { return Err(Failure { expected: Type::Variable(index), found, occurs: true, nested }); }
            self.bind(index, found); return Ok(());
        }
        if let Type::Variable(index) = found {
            if self.variables(&expected).contains(&index) { return Err(Failure { expected, found: Type::Variable(index), occurs: true, nested }); }
            self.bind(index, expected); return Ok(());
        }
        match (&expected, &found) {
            (Type::List(a), Type::List(b)) => self.unify_at(a, b, true),
            (Type::Pair(a, b), Type::Pair(c, d)) | (Type::Function(a, b), Type::Function(c, d)) => { self.unify_at(a, c, true)?; self.unify_at(b, d, true) },
            _ => Err(Failure { expected, found, occurs: false, nested })
        }
    }
    pub fn generalize(&self, ty: Type, environment: &Environment) -> Scheme {
        let mut variables = self.variables(&ty);
        for scheme in environment.values() {
            for index in self.variables(&scheme.ty).difference(&scheme.quantified) { variables.remove(index); }
        }
        Scheme { ty, quantified: variables }
    }
    pub fn instantiate(&mut self, scheme: &Scheme) -> Type {
        let replacements: BTreeMap<_, _> = scheme.quantified.iter().map(|&i| (i, self.fresh())).collect();
        fn replace(ty: Type, replacements: &BTreeMap<usize, Type>) -> Type {
            match ty { Type::Variable(i) => replacements.get(&i).cloned().unwrap_or(Type::Variable(i)), Type::List(ty) => Type::list(replace(*ty, replacements)), Type::Pair(a, b) => Type::pair(replace(*a, replacements), replace(*b, replacements)), Type::Function(a, b) => Type::function(replace(*a, replacements), replace(*b, replacements)), _ => ty }
        }
        replace(self.resolve(&scheme.ty), &replacements)
    }
}
